import { useEffect, useRef } from 'react';
import * as THREE from 'three';

function createBallpit(canvas, config = {}) {
  const parent = canvas.parentElement;

  const width = parent.clientWidth;
  const height = parent.clientHeight;

  // Renderer
  const renderer = new THREE.WebGLRenderer({
    canvas,
    antialias: true,
    alpha: true,
  });

  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.setSize(width, height);

  // Scene
  const scene = new THREE.Scene();

  // Camera
  const camera = new THREE.PerspectiveCamera(50, width / height, 0.1, 100);
  camera.position.z = 15;

  // Lights
  const ambient = new THREE.AmbientLight(0xffffff, 0.6);
  scene.add(ambient);

  const light = new THREE.PointLight(0xffffff, 300);
  light.position.set(5, 5, 10);
  scene.add(light);

  // Geometry
  const geometry = new THREE.SphereGeometry(1, 32, 32);

  // Colors
  const colors = ['#7c3aed', '#ffffff', '#4f46e5', '#111827'];

  const meshes = [];

  const count = config.count || 40;

  for (let i = 0; i < count; i++) {
    const material = new THREE.MeshStandardMaterial({
      color: new THREE.Color(colors[Math.floor(Math.random() * colors.length)]),
      roughness: 0.3,
      metalness: 0.6,
    });

    const mesh = new THREE.Mesh(geometry, material);

    mesh.position.set(
      (Math.random() - 0.5) * 10,
      (Math.random() - 0.5) * 10,
      (Math.random() - 0.5) * 5
    );

    scene.add(mesh);
    meshes.push(mesh);
  }

  const velocities = meshes.map(() => ({
    x: (Math.random() - 0.5) * 0.05,
    y: (Math.random() - 0.5) * 0.05,
    z: (Math.random() - 0.5) * 0.05,
  }));

  // Animation
  function animate() {
    requestAnimationFrame(animate);

    meshes.forEach((mesh, i) => {
      const v = velocities[i];

      mesh.position.x += v.x;
      mesh.position.y += v.y;
      mesh.position.z += v.z;

      if (Math.abs(mesh.position.x) > 5) v.x *= -1;
      if (Math.abs(mesh.position.y) > 5) v.y *= -1;
      if (Math.abs(mesh.position.z) > 3) v.z *= -1;
    });

    renderer.render(scene, camera);
  }

  animate();

  // Resize
  function resize() {
    const w = parent.clientWidth;
    const h = parent.clientHeight;

    renderer.setSize(w, h);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
  }

  window.addEventListener('resize', resize);

  return {
    dispose() {
      window.removeEventListener('resize', resize);
      renderer.dispose();
    },
  };
}

const Ballpit = ({ className = '', ...props }) => {
  const canvasRef = useRef(null);
  const instanceRef = useRef(null);

  useEffect(() => {
    if (!canvasRef.current) return;

    instanceRef.current = createBallpit(canvasRef.current, props);

    return () => {
      instanceRef.current?.dispose();
    };
  }, []);

  return (
    <canvas
      ref={canvasRef}
      className={className}
      style={{
        width: '100%',
        height: '100%',
        display: 'block',
      }}
    />
  );
};

export default Ballpit;
